namespace ProjectEuler
{
    public class Problem070
    {
        private Problem070() { } // Singleton pattern

        private static readonly Lazy<Problem070> lazy = new Lazy<Problem070>(() => new Problem070());

        public static int Solve()
        {
            int total = 1;

            int index = 1;
            while (total < 1000000)
            {
                int count = 0;
                int x = index;
                while (x % 10 != 0)
                {
                    x /= 10;
                    count++;
                }
                //Console.WriteLine("Count for {0} : {1}", index, count);
                if (count % 2 == 0)
                {
                    total += index;
                }
                index++;
            }

            return total;
        }
    }
}
